// agent-profiles.mjs — the job description ("fisa postului") of every office agent: one Markdown file with a small
// YAML frontmatter per role (docs/agent-job-description-options.md, option A). From it we derive the prompt every brain
// receives, the A2A Agent Card, the Claude Code subagent file and the check against what each CLI can enforce.
//
// Precedence when loading: a valid override in <home>/agent-profiles/<role>.md, else the shipped file
// server/agent-profiles/<role>.md (generated by scripts/gen-agent-profiles.mjs), else the in-code default.
import { createHash, randomBytes } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { ACCESS_ENFORCEMENT, adapters } from './adapters.mjs'
import { officeHome } from './paths.mjs'
import { DEFAULT_ROLE, PROFILES, ROLES, listRoles } from './roles.mjs'

export const TOOLS = ['Read', 'Grep', 'Glob', 'Bash(read-only)', 'Bash', 'Write', 'Edit', 'WebFetch', 'Task']
const MODELS = ['fast', 'balanced', 'strong', 'inherit']
const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max']
const STATUSES = ['default', 'draft', 'approved']
const CHAT_ACCESS = ['none', 'read']
const WRITE_ACCESS = ['edit-after-approval', 'edit-and-run-after-approval']
const SECTIONS = ['Who you are', 'Mission and responsibilities', 'What you receive and what you hand back', 'What you must not do', 'Ask the boss first when', 'Definition of done']
const TOP_KEYS = ['name', 'description', 'tools', 'disallowedTools', 'model', 'effort', 'office']
const OFFICE_KEYS = ['displayName', 'reportsTo', 'routes', 'access', 'mayDelegateTo', 'escalatesTo', 'status', 'locked']
const ROLE_ID = /^[a-z0-9][a-z0-9-]{0,63}$/
const MAX_BYTES = 20 * 1024
const SHIPPED_DIR = fileURLToPath(new URL('./agent-profiles/', import.meta.url))

export class ProfileError extends Error {
  constructor(errors) {
    const list = (Array.isArray(errors) ? errors : [{ message: String(errors) }]).map(e => ({ line: 1, ...e }))
    super(list.map((e) => `${e.line ? `line ${e.line}: ` : ''}${e.field ? `${e.field}: ` : ''}${e.message}`).join('; '))
    this.name = 'ProfileError'
    this.errors = list
  }
}

// ---------------------------------------------------------------------------------------------------------------
// YAML subset parser.
// shortcut: only the subset below (scalars, inline lists/maps, block lists, one nested map level, # comments). No block
// scalars (| >), anchors, tags, multi-line values or multiple documents. Upgrade to a real YAML library if users start
// writing arbitrary YAML.

const fail = (line, message) => { throw new ProfileError([{ line, message }]) }

/** Remove a trailing `# comment` that sits outside quotes. */
function stripComment(s) {
  let q = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (q) {
      if (q === '"' && c === '\\') i++
      else if (c === q) { if (q === "'" && s[i + 1] === "'") i++; else q = '' }
    } else if ((c === '"' || c === "'") && !/[A-Za-z0-9]/.test(s[i - 1] ?? ' ')) q = c
    else if (c === '#' && (i === 0 || /\s/.test(s[i - 1]))) return s.slice(0, i)
  }
  return s
}

/** Split on top-level commas (outside quotes and brackets). */
function splitTop(s) {
  const out = []
  let q = ''; let depth = 0; let cur = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (q) {
      cur += c
      if (q === '"' && c === '\\') cur += s[++i] ?? ''
      else if (c === q) q = ''
    } else if ((c === '"' || c === "'") && !/[A-Za-z0-9]/.test(s[i - 1] ?? ' ')) { q = c; cur += c }
    else if (c === '[' || c === '{') { depth++; cur += c }
    else if (c === ']' || c === '}') { depth--; cur += c }
    else if (c === ',' && depth === 0) { out.push(cur.trim()); cur = '' }
    else cur += c
  }
  if (cur.trim() || out.length) out.push(cur.trim())
  return out
}

function parseScalar(raw, line, { list = false, map = false } = {}) {
  const s = raw.trim()
  if (s === '') fail(line, 'empty value')
  if (s[0] === '"') {
    if (s.length < 2 || s.at(-1) !== '"') fail(line, 'unterminated double-quoted string')
    try { return JSON.parse(s) } catch { return fail(line, 'invalid escape in double-quoted string') }
  }
  if (s[0] === "'") {
    if (s.length < 2 || s.at(-1) !== "'") fail(line, 'unterminated single-quoted string')
    return s.slice(1, -1).replaceAll("''", "'")
  }
  if (s[0] === '[') {
    if (!list || s.at(-1) !== ']') fail(line, list ? 'unterminated inline list' : 'a list is not allowed here')
    return splitTop(s.slice(1, -1)).map((x) => parseScalar(x, line))
  }
  if (s[0] === '{') {
    if (!map || s.at(-1) !== '}') fail(line, map ? 'unterminated inline map' : 'a map is not allowed here')
    const out = {}
    for (const part of splitTop(s.slice(1, -1))) {
      const m = /^([A-Za-z0-9_-]+):(?:\s+(.*))?$/.exec(part)
      if (!m || m[2] === undefined) fail(line, `bad inline map entry "${part}"`)
      if (m[1] === '__proto__' || m[1] in out) fail(line, `duplicate or forbidden key "${m[1]}"`)
      out[m[1]] = parseScalar(m[2], line)
    }
    return out
  }
  if (/^[|>][-+]?$/.test(s)) fail(line, 'block scalars are not supported')
  if (/^[&*!%@`]/.test(s)) fail(line, 'anchors, aliases and tags are not supported')
  if (s === 'true') return true
  if (s === 'false') return false
  if (s === 'null') return null
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s)
  return s
}

const KEY_LINE = /^([A-Za-z0-9_-]+):(?:\s+(.*))?$/

/** Parse a profile file into { frontmatter, body }. Throws ProfileError with line numbers. */
export function parseProfile(text) {
  const lines = String(text).replace(/\r\n?/g, '\n').split('\n')
  if (lines[0] !== '---') fail(1, 'the file must start with a "---" line')
  const end = lines.indexOf('---', 1)
  if (end < 0) fail(1, 'the frontmatter is not closed by a "---" line')
  const fm = {}
  const sourceLines = { fields: {}, items: {}, headings: [], last: lines.length, body: end + 2 }
  const record = (key, value, ln) => {
    sourceLines.fields[key] = ln
    if (Array.isArray(value)) sourceLines.items[key] = value.map(() => ln)
    else if (value && typeof value === 'object') for (const [k, v] of Object.entries(value)) record(`${key}.${k}`, v, ln)
  }
  let cur = null // { key, kind: null | 'list' | 'map' } while a block under a key is open
  for (let i = 1; i < end; i++) {
    const ln = i + 1
    const raw = lines[i]
    if (/^[ ]*\t/.test(raw)) fail(ln, 'tabs are not allowed, indent with spaces')
    const line = stripComment(raw).trimEnd()
    if (line.trim() === '') continue
    const indent = line.length - line.trimStart().length
    const rest = line.trim()
    if (indent === 0) {
      cur = null
      const m = KEY_LINE.exec(rest)
      if (!m) fail(ln, 'expected "key: value"')
      if (m[1] === '__proto__' || Object.hasOwn(fm, m[1])) fail(ln, `duplicate or forbidden key "${m[1]}"`)
      if (m[2] === undefined) { fm[m[1]] = null; cur = { key: m[1], kind: null } } else fm[m[1]] = parseScalar(m[2], ln, { list: true, map: true })
      record(m[1], fm[m[1]], ln)
    } else if (indent === 2 && cur) {
      if (rest === '-' || rest.startsWith('- ')) {
        if (cur.kind === 'map') fail(ln, 'cannot mix a list and a map under one key')
        if (cur.kind === null) { cur.kind = 'list'; fm[cur.key] = [] }
        fm[cur.key].push(parseScalar(rest.slice(1), ln))
        ;(sourceLines.items[cur.key] ??= []).push(ln)
      } else {
        const m = KEY_LINE.exec(rest)
        if (!m) fail(ln, 'unknown structure, expected "key: value" or "- item"')
        if (cur.kind === 'list') fail(ln, 'cannot mix a list and a map under one key')
        if (m[2] === undefined) fail(ln, 'only one nested level is supported')
        if (cur.kind === null) { cur.kind = 'map'; fm[cur.key] = {} }
        if (m[1] === '__proto__' || Object.hasOwn(fm[cur.key], m[1])) fail(ln, `duplicate or forbidden key "${m[1]}"`)
        fm[cur.key][m[1]] = parseScalar(m[2], ln, { list: true, map: true })
        record(`${cur.key}.${m[1]}`, fm[cur.key][m[1]], ln)
      }
    } else fail(ln, 'unknown structure (bad indentation)')
  }
  const bodyLines = lines.slice(end + 1)
  while (bodyLines[0] === '') { bodyLines.shift(); sourceLines.body++ }
  const body = bodyLines.join('\n').trimEnd()
  sourceLines.headings = sections(body).map(s => ({ title: s.title, line: sourceLines.body + s.offset }))
  return Object.defineProperty({ frontmatter: fm, body }, 'sourceLines', { value: sourceLines })
}

// ---------------------------------------------------------------------------------------------------------------
// Serializer (canonical form)

const plainOk = (s) => s !== '' && s === s.trim() && !/^[-?:,[\]{}#&*!|>'"%@`]/.test(s) && !/[,[\]{}\n\r\t]|: | #|:$/.test(s) && !/^(true|false|null|-?\d+(\.\d+)?)$/.test(s)
const scalar = (v) => (typeof v === 'string' ? (plainOk(v) ? v : JSON.stringify(v)) : String(v))
function inline(v) {
  if (Array.isArray(v)) return v.length ? `[${v.map(scalar).join(', ')}]` : '[]'
  if (v && typeof v === 'object') return `{ ${Object.entries(v).map(([k, x]) => `${k}: ${scalar(x)}`).join(', ')} }`
  return scalar(v)
}
const orderKeys = (obj, order) => [...order.filter((k) => k in obj), ...Object.keys(obj).filter((k) => !order.includes(k))]

/** The canonical text of a profile: stable key order, LF line endings. */
export function serializeProfile({ frontmatter, body }) {
  const out = ['---']
  for (const k of orderKeys(frontmatter, TOP_KEYS)) {
    const v = frontmatter[k]
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      out.push(`${k}:`)
      for (const s of orderKeys(v, OFFICE_KEYS)) out.push(`  ${s}: ${inline(v[s])}`)
    } else out.push(`${k}: ${inline(v)}`)
  }
  out.push('---', String(body).trim(), '')
  return out.join('\n')
}

// ---------------------------------------------------------------------------------------------------------------
// Validator

/** [{ title, content }] for every level-1 heading of the body (headings inside code fences are ignored). */
function sections(body) {
  const out = []
  let fence = false
  for (const [offset, line] of String(body).split('\n').entries()) {
    if (/^\s*```/.test(line)) fence = !fence
    const m = !fence && /^# (.+?)\s*$/.exec(line)
    if (m) out.push({ title: m[1], content: '', offset })
    else if (out.length) out.at(-1).content += `${line}\n`
  }
  return out
}

const isStrArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string' && x.trim() !== '')

/** Validate a parsed profile. `roles` is listRoles() (objects or ids); `role` (optional) is the id the name must equal. */
export function validateProfile(profile, { roles = listRoles(), role } = {}) {
  const { frontmatter: fm, body } = profile
  const errors = []
  const source = profile.sourceLines ?? (fm && typeof fm === 'object' ? parseProfile(serializeProfile(profile)).sourceLines : { fields: {}, items: {}, headings: [], last: 1 })
  const fieldLine = (field) => {
    let key = field
    while (key) {
      if (source.fields[key]) return source.fields[key]
      key = key.includes('.') ? key.slice(0, key.lastIndexOf('.')) : ''
    }
    return 1
  }
  const bad = (field, message, line = fieldLine(field)) => errors.push({ field, message, line })
  const itemLine = (key, invalid) => source.items[key]?.[invalid] ?? fieldLine(key)
  const ids = roles.map((r) => (typeof r === 'string' ? r : r.role))
  const known = (v) => typeof v === 'string' && ids.includes(v)
  if (!fm || typeof fm !== 'object') return { ok: false, errors: [{ message: 'missing frontmatter', line: 1 }] }
  for (const k of Object.keys(fm)) if (!TOP_KEYS.includes(k)) bad(k, 'unknown field')

  if (typeof fm.name !== 'string' || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(fm.name) || fm.name.length > 64) bad('name', 'must be kebab-case, at most 64 characters')
  else if (role ? fm.name !== role : !known(fm.name)) bad('name', role ? `must equal the role id "${role}"` : 'must be a known role id')
  if (typeof fm.description !== 'string' || fm.description.length < 20 || fm.description.length > 500) bad('description', 'must be a string of 20 to 500 characters')

  for (const k of ['tools', 'disallowedTools']) {
    if (fm[k] === undefined && k === 'disallowedTools') continue
    if (!Array.isArray(fm[k]) || !fm[k].every((t) => TOOLS.includes(t))) bad(k, `must be a list from: ${TOOLS.join(', ')}`, itemLine(k, fm[k]?.findIndex?.(t => !TOOLS.includes(t))))
  }
  if (!MODELS.includes(fm.model)) bad('model', `must be one of ${MODELS.join(', ')}`)
  if (!EFFORTS.includes(fm.effort)) bad('effort', `must be one of ${EFFORTS.join(', ')}`)

  const o = fm.office
  if (!o || typeof o !== 'object' || Array.isArray(o)) bad('office', 'missing office block')
  else {
    for (const k of Object.keys(o)) if (!OFFICE_KEYS.includes(k)) bad(`office.${k}`, 'unknown field')
    if (typeof o.displayName !== 'string' || !o.displayName.trim()) bad('office.displayName', 'must be a non-empty string')
    if (o.reportsTo !== null && !known(o.reportsTo)) bad('office.reportsTo', 'must be a known role id or null')
    if (!isStrArray(o.routes)) bad('office.routes', 'must be a list of strings', itemLine('office.routes', o.routes?.findIndex?.(x => typeof x !== 'string' || !x.trim())))
    const a = o.access
    if (!a || typeof a !== 'object' || Array.isArray(a)) bad('office.access', 'must be a map with chat, plan and (optionally) write')
    else {
      if (!CHAT_ACCESS.includes(a.chat)) bad('office.access.chat', `must be one of ${CHAT_ACCESS.join(', ')}`)
      if (a.plan !== 'read') bad('office.access.plan', 'must be read')
      if (a.write !== undefined && !WRITE_ACCESS.includes(a.write)) bad('office.access.write', `must be one of ${WRITE_ACCESS.join(', ')}`)
      for (const k of Object.keys(a)) if (!['chat', 'plan', 'write'].includes(k)) bad(`office.access.${k}`, 'unknown field')
    }
    if (!Array.isArray(o.mayDelegateTo) || !o.mayDelegateTo.every(known)) bad('office.mayDelegateTo', 'must be a list of known role ids', itemLine('office.mayDelegateTo', o.mayDelegateTo?.findIndex?.(x => !known(x))))
    if (o.escalatesTo !== 'boss' && !known(o.escalatesTo)) bad('office.escalatesTo', 'must be boss or a known role id')
    if (!STATUSES.includes(o.status)) bad('office.status', `must be one of ${STATUSES.join(', ')}`)
    if (o.locked !== undefined && typeof o.locked !== 'boolean') bad('office.locked', 'must be true or false')
    const writeTools = (Array.isArray(fm.tools) ? fm.tools : []).filter((t) => ['Write', 'Edit', 'Bash'].includes(t))
    const denied = Array.isArray(fm.disallowedTools) ? fm.disallowedTools : []
    for (const t of writeTools) if (denied.includes(t)) bad('tools', `${t} is both allowed and disallowed`, itemLine('tools', fm.tools.indexOf(t)))
    if ((fm.tools ?? []).some?.((t) => t === 'Write' || t === 'Edit') && !o.access?.write) bad('tools', 'Write/Edit need office.access.write', itemLine('tools', fm.tools.findIndex(t => t === 'Write' || t === 'Edit')))
  }

  const found = sections(body)
  let at = 0
  for (const title of SECTIONS) {
    const i = found.findIndex((s, j) => j >= at && s.title === title)
    if (i < 0) { bad('body', `missing or out-of-order heading "# ${title}"`, source.headings.find(s => s.title === title)?.line ?? source.headings[at]?.line ?? source.last); continue }
    at = i + 1
    if (!found[i].content.trim()) bad('body', `section "${title}" is empty`, source.body + found[i].offset)
  }
  if (!errors.length && Buffer.byteLength(serializeProfile({ frontmatter: fm, body })) > MAX_BYTES) bad('file', 'larger than 20 KB', 1)
  return { ok: errors.length === 0, errors }
}

