const READ_TOOLS = ['Read', 'Grep', 'Glob', 'Bash(read-only)']
const FAMILY = {
  'read-only': { tools: READ_TOOLS, disallowed: ['Write', 'Edit'], write: undefined },
  assistant: { tools: ['Read', 'Grep', 'Glob'], disallowed: ['Write', 'Edit', 'Bash'], write: undefined },
  implementer: { tools: [...READ_TOOLS, 'Write', 'Edit'], disallowed: [], write: 'edit-after-approval' },
  runner: { tools: ['Read', 'Grep', 'Glob', 'Bash', 'Write', 'Edit'], disallowed: [], write: 'edit-and-run-after-approval' },
}

function knownRole(role) {
  const entry = typeof role === 'string' && ROLE_ID.test(role) ? listRoles().find((r) => r.role === role) : undefined
  if (!entry) throw new ProfileError([{ field: 'role', message: `unknown or invalid role id: ${String(role).slice(0, 80)}` }])
  return entry
}

/** The in-code default job description of a role: { frontmatter, body }. */
export function defaultProfile(role) {
  const entry = knownRole(role)
  const p = PROSE[role]
  const fam = FAMILY[p.family]
  const prof = PROFILES[role]
  const routes = role === DEFAULT_ROLE.role ? [] : [...new Set(ROLES.filter((r) => r.role === role).flatMap((r) => r.words))]
  const reports = listRoles().filter((r) => r.reportsTo === role).map((r) => r.role)
  const access = { chat: role === DEFAULT_ROLE.role ? 'none' : 'read', plan: 'read', ...(fam.write ? { write: fam.write } : {}) }
  const bullets = (xs) => xs.map((x) => `- ${x}`).join('\n')
  const body = [
    '# Who you are',
    `You are the ${entry.name} of this office. ${p.who}`,
    '# Mission and responsibilities',
    `${p.desc.split('. ')[0].replace(/\.$/, '')}. Your responsibilities:`,
    bullets(p.duties),
    '# What you receive and what you hand back',
    `You receive: ${p.input}`,
    `You hand back: ${p.output}`,
    '# What you must not do',
    bullets([...COMMON_NO, ...p.no]),
    '# Ask the boss first when',
    bullets(p.ask),
    '# Definition of done',
    bullets(p.done),
  ].join('\n')
  return {
    frontmatter: {
      name: role,
      description: p.desc,
      tools: [...fam.tools],
      disallowedTools: [...fam.disallowed],
      model: prof.tier,
      effort: prof.effort,
      office: { displayName: entry.name, reportsTo: entry.reportsTo, routes, access, mayDelegateTo: reports, escalatesTo: entry.reportsTo ?? 'boss', status: 'default', locked: false },
    },
    body,
  }
}

// ---------------------------------------------------------------------------------------------------------------
// Loading and saving

const hashOf = (profile) => createHash('sha256').update(serializeProfile(profile)).digest('hex').slice(0, 12)
const overrideFile = (home, role) => join(home, 'agent-profiles', `${role}.md`)

/** Read and validate one file; { profile } or { error }. */
function readProfileFile(file, role) {
  try {
    const profile = parseProfile(readFileSync(file, 'utf8'))
    const v = validateProfile(profile, { role })
    return v.ok ? { profile } : { error: new ProfileError(v.errors) }
  } catch (e) {
    return { error: e instanceof ProfileError ? e : new ProfileError([{ message: String(e?.message ?? e) }]) }
  }
}

/** The effective profile of a role: { role, profile, source: 'override'|'shipped'|'generated', warnings, hash }. */
export function loadProfile(role, { home } = {}) {
  knownRole(role)
  const warnings = []
  for (const [source, file] of [['override', overrideFile(home ?? officeHome(), role)], ['shipped', join(SHIPPED_DIR, `${role}.md`)]]) {
    if (!existsSync(file)) continue
    const { profile, error } = readProfileFile(file, role)
    if (profile) return { role, profile, source, warnings, hash: hashOf(profile) }
    warnings.push(`${source} profile ignored: ${error.message}`)
  }
  const profile = defaultProfile(role)
  return { role, profile, source: 'generated', warnings, hash: hashOf(profile) }
}

export function listProfiles({ home } = {}) {
  return listRoles().map((r) => loadProfile(r.role, { home }))
}

/** Validate `text` and store it as the office override of `role`. Throws ProfileError; nothing is written when invalid. */
export function saveProfile(role, text, { home, status } = {}) {
  knownRole(role)
  const base = home ?? officeHome()
  const profile = parseProfile(text)
  if (status !== undefined && profile.frontmatter.office && typeof profile.frontmatter.office === 'object') profile.frontmatter.office.status = status
  const v = validateProfile(profile, { role })
  if (!v.ok) throw new ProfileError(v.errors)
  const file = overrideFile(base, role)
  if (existsSync(file)) {
    const current = readProfileFile(file, role).profile
    if (current?.frontmatter.office.locked === true && hashOf(current) !== hashOf(profile)) {
      throw new ProfileError([{ field: 'office.locked', line: profile.sourceLines?.fields['office.locked'] ?? 1, message: `the profile of ${role} is locked; unlock it before changing it` }])
    }
  }
  mkdirSync(join(base, 'agent-profiles'), { recursive: true })
  const tmp = `${file}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`
  try {
    writeFileSync(tmp, serializeProfile(profile), { mode: 0o600 })
    renameSync(tmp, file)
  } catch (e) {
    rmSync(tmp, { force: true })
    throw e
  }
  return loadProfile(role, { home: base })
}

/** Remove the office override so the shipped profile applies again. Returns true when there was one. */
export function resetProfile(role, { home } = {}) {
  knownRole(role)
  const file = overrideFile(home ?? officeHome(), role)
  const had = existsSync(file)
  rmSync(file, { force: true })
  return had
}

// ---------------------------------------------------------------------------------------------------------------
// Derived artifacts

/** The job description every brain receives: a one-line header and the body. No frontmatter. */
export function profileSystemPrompt(profile, { cwd } = {}) {
  const o = profile.frontmatter.office
  return `You are ${o.displayName}, the office ${profile.frontmatter.name}. You report to ${o.reportsTo ?? 'the boss'}. Project folder: ${cwd ?? 'the current folder'}.\n\n${profile.body.trim()}\n`
}

const responsibilities = (body) => (sections(body).find((s) => s.title === 'Mission and responsibilities')?.content ?? '')
  .split('\n').map((l) => /^\s*[-*]\s+(.+)$/.exec(l)?.[1]).filter(Boolean)

/** The A2A (v0.3.0) Agent Card of one agent. */
export function agentCard(profile, { url } = {}) {
  const { name, description, office } = profile.frontmatter
  return {
    name: office.displayName,
    description,
    version: '1',
    protocolVersion: '0.3.0',
    url: url ?? '',
    preferredTransport: 'JSONRPC',
    capabilities: { streaming: false, pushNotifications: false, stateTransitionHistory: false },
    defaultInputModes: ['text/plain'],
    defaultOutputModes: ['text/plain'],
    skills: responsibilities(profile.body).map((b, i) => ({
      id: `${name}-${i + 1}`,
      name: b.split(/\s+/).slice(0, 6).join(' '),
      description: b,
      tags: [...office.routes],
      examples: office.routes.slice(0, 2).map((w) => `Please help me with this ${w}.`),
    })),
    securitySchemes: { bearer: { type: 'http', scheme: 'bearer' } },
    security: [{ bearer: [] }],
  }
}

const CLAUDE_MODEL = { fast: 'haiku', balanced: 'sonnet', strong: 'opus', inherit: 'inherit' }

/** The text of `.claude/agents/<name>.md` (https://code.claude.com/docs/en/sub-agents); the office block is not emitted. */
export function claudeAgentFile(profile) {
  const f = profile.frontmatter
  const lines = ['---', `name: ${f.name}`, `description: ${scalar(f.description)}`, `tools: ${f.tools.join(', ')}`]
  if (f.disallowedTools?.length) lines.push(`disallowedTools: ${f.disallowedTools.join(', ')}`)
  lines.push(`model: ${CLAUDE_MODEL[f.model]}`, `effort: ${f.effort}`, '---', profile.body.trim(), '')
  return lines.join('\n')
}

const RANK = { soft: 0, 'read-enforced': 1, none: 2, 'edit-enforced': 1 }

/** Where the profile wants a stronger boundary than the CLI of `service` enforces: [{ mode, wanted, guaranteed, message }]. */
export function checkAccess(profile, service) {
  const enforced = ACCESS_ENFORCEMENT[service]
  if (!enforced) return [{ mode: '*', wanted: '*', guaranteed: 'unknown', message: `unknown service ${service}` }]
  const a = profile.frontmatter.office.access
  const wants = { chat: a.chat === 'none' ? 'none' : 'read-enforced', plan: 'read-enforced', ...(a.write ? { write: 'edit-enforced' } : {}) }
  const out = []
  for (const [mode, wanted] of Object.entries(wants)) {
    const guaranteed = enforced[mode]
    const ok = mode === 'write' ? guaranteed === wanted : RANK[guaranteed] >= RANK[wanted]
    if (!ok) out.push({ mode, wanted, guaranteed, message: `${service} ${mode} mode is "${guaranteed}" but ${profile.frontmatter.name} needs "${wanted}"` })
  }
  return out
}

/** Summarize only the supplied services; checking capabilities never starts a CLI. */
export function summarizeAccess(profile, services) {
  const byService = [...new Set(services.map(s => typeof s === 'string' ? s : s.name ?? s.service))].flatMap(service => {
    const issues = checkAccess(profile, service).map(({ mode, wanted, guaranteed }) => ({ mode, wanted, guaranteed }))
    return issues.length ? [{ service, label: adapters[service]?.label ?? service, issues }] : []
  })
  const groups = new Map()
  for (const { label, issues } of byService) for (const issue of issues) {
    const key = JSON.stringify(issue)
    if (!groups.has(key)) groups.set(key, { ...issue, labels: [] })
    groups.get(key).labels.push(label)
  }
  const joinLabels = labels => labels.length < 3 ? labels.join(' and ') : `${labels.slice(0, -1).join(', ')} and ${labels.at(-1)}`
  const text = [...groups.values()].map(({ mode, wanted, labels }) => `${joinLabels(labels)} cannot guarantee ${wanted === 'none' ? 'no tool access' : wanted === 'read-enforced' ? 'read-only' : wanted === 'edit-enforced' ? 'approved edits' : 'the requested access'} in ${mode} mode.`).join(' ')
  return { count: byService.reduce((n, s) => n + s.issues.length, 0), byService, text }
}
